/** The mark for a stack entry or issuer, or null when nothing legitimate matches. */
export function brandIcon(name: string): BrandIcon | null {
  const haystack = name.toLowerCase();
  for (const [needle, icon] of BRAND_ICONS) {
    if (haystack.includes(needle)) return icon;
  }
  return null;
}
